// spec: specs/chat-conversations.md (2.3) · кейс: .qa/tests/chat-conversations/CHAT-OPEN-03.md (обновлён по #c5ed06: меню под списком)
// seed: tests/seed.chat.spec.ts · прод, только чтение (запись заблокирована).
import { test, expect } from '@playwright/test';
import {
  blockWrites, LOAD, CONVERSATION_TITLE, CONVERSATION_URL, messageInput, personalAreaHeading,
} from './open-conversation.helpers';

test.use({ storageState: '../auth/chat.json', serviceWorkers: 'block' });

test.describe('Чат / переписки — открытие переписки', () => {
  test('Мобайл: «חזרה לשיחות» возвращает к списку переписок #bb6e6d #c5ed06 @mobile @prod-safe', async ({ page }) => {
    await blockWrites(page);
    await page.goto(CONVERSATION_URL);
    await expect(messageInput(page)).toBeVisible(LOAD);

    await page.getByRole('button', { name: 'חזרה לשיחות' }).click();

    await page.waitForURL((url) => url.pathname === '/messages' && !url.searchParams.has('conversation'));
    await expect(messageInput(page)).toHaveCount(0);
    const listItem = page.getByRole('heading', { name: CONVERSATION_TITLE });
    await expect(listItem, 'переписка в списке видна').toBeInViewport(LOAD);
    await expect(page.getByPlaceholder('חפש שיחות...'), 'поиск по перепискам виден').toBeInViewport();
    await expect(page.getByRole('heading', { name: 'שיחות', exact: true })).toBeInViewport();

    // Меню «אזור אישי» снова показано и стоит НИЖЕ списка (#c5ed06, PR #167: на мобайле список до меню)
    const menu = personalAreaHeading(page);
    await expect(menu).toBeVisible();
    const menuBox = await menu.boundingBox();
    const listBox = await listItem.boundingBox();
    expect(menuBox!.height, 'высота «אזור אישי» > 0').toBeGreaterThan(0);
    expect(menuBox!.y, 'меню ниже списка').toBeGreaterThan(listBox!.y + listBox!.height);
  });
});
